157	/// Helper function to build a new value.
158	fn create_new_local_value<'a>(
159	    program: &'a mut Program,
160	    my_ir_generator_info: &'a mut MyIRGeneratorInfo,
161	) -> koopa::ir::builder::LocalBuilder<'a> {
162	    program
163	        .func_mut(
164	            my_ir_generator_info
165	                .curr_func
166	                .expect("You should use create_new_global_value when curr_func is None! "),
167	        )
168	        .dfg_mut()
169	        .new_value()
170	}
