235	fn get_array_type(btype: &BType, shape: &[usize]) -> TypeKind {
236	    if shape.is_empty() {
237	        return btype.content.clone();
238	    }
239	    let inner_typekind = get_array_type(btype, &shape[1..]);
240	    TypeKind::Array(Type::get(inner_typekind), shape[0])
241	}
