1	//! Definition of the Abstract Syntax Tree (AST).
2	//!
3	//!
4	//! Currently, AST is defined as follows:
5	//!
6	//! CompUnit ::= {Unit};
7	//! Unit     ::= Decl | FuncDef;
8	//!
9	//! ======================================================
10	//! Declarations
11	//! ======================================================
12	//! FuncDef       ::= FuncType IDENT "(" [FuncFParams] ")" Block;
13	//! FuncFParams   ::= FuncFParam {"," FuncFParam};
14	//! FuncFParam    ::= BType IDENT ["[" "]" {"[" Exp "]"}]; // Exp should be const
15	//!
16	//! Block         ::= "{" {BlockItem} "}";
17	//! BlockItem     ::= Decl | Stmt;
18	//!
19	//! Decl          ::= ConstDecl | VarDecl;
20	//!
21	//! ConstDecl     ::= "const" BType ConstDef {"," ConstDef} ";";
22	//! ConstDef      ::= IDENT {"[" Exp "]"} "=" InitVal;
23	//!                 // Exps and InitVal should be const. Checked at semantic level.
24	//!
25	//! VarDecl       ::= BType VarDef {"," VarDef} ";";
26	//! VarDef        ::= IDENT {"[" Exp "]"}
27	//!                 | IDENT {"[" Exp "]"} "=" InitVal;
28	//!                 // If this VarDef is global, InitVal should be const.
29	//!                 // Exps in indexes should be const. Checked at semantic level.
30	//!                 // This check is done in semantic analysis, not in syntax analysis.
31	//!
32	//! ======================================================
33	//! Statements
34	//! ======================================================
35	//! Stmt ::= UnmatchedStmt
36	//!        | MatchedStmt;
37	//!
38	//! UnmatchedStmt ::= "if" "(" Exp ")" MatchedStmt ["else" UnmatchedStmt]
39	//!                 | "if" "(" Exp ")" UnmatchedStmt
40	//!                 | "while" "(" Exp ")" UnmatchedStmt;
41	//!
42	//! MatchedStmt ::= LVal "=" Exp ";"
43	//!               | [Exp] ";"
44	//!               | Block
45	//!               | "if" "(" Exp ")" MatchedStmt "else" MatchedStmt
46	//!               | "while" "(" Exp ")" MatchedStmt
47	//!               | "break" ";"
48	//!               | "continue" ";"
49	//!               | "return" [Exp] ";";
50	//!
51	//! ======================================================
52	//! Expressions
53	//! ======================================================
54	//! InitVal       ::= Exp
55	//!                 | "{" "}"
56	//!                 | "{" InitVal {"," InitVal} "}";
57	//!                 // The check of "whether an exp is const" is done in semantic analysis.
58	//!
59	//! Exp         ::= LOrExp;
60	//!
61	//! LOrExp      ::= LAndExp | LOrExp "||" LAndExp;
62	//! LAndExp     ::= EqExp | LAndExp "&&" EqExp;
63	//! EqExp       ::= RelExp | EqExp ("==" | "!=") RelExp;
64	//! RelExp      ::= AddExp | RelExp ("<" | ">" | "<=" | ">=") AddExp;
65	//!
66	//! AddExp      ::= MulExp | AddExp ("+" | "-") MulExp;
67	//! MulExp      ::= UnaryExp | MulExp ("*" | "/" | "%") UnaryExp;
68	//!
69	//! UnaryExp    ::= PrimaryExp
70	//!               | UnaryOp UnaryExp
71	//!               | IDENT "(" [FuncRParams] ")";
72	//! UnaryOp     ::= "+" | "-" | "!";
73	//! PrimaryExp  ::= "(" Exp ")" | LVal | Number;
74	//!
75	//! LVal        ::= IDENT {"[" Exp "]"};
76	//! Number      ::= INTCONST;
77	//!
78	//! ======================================================
79	//! Symbols
80	//! ======================================================
81	//! // FuncType  ::= "void" | "int"; (Currently removed to aviod lalrpop conflict. )
82	//! BType     ::= "int";
83	//!
