145	) -> ValueData {
146	    if value.is_global() {
147	        program.borrow_value(value).clone()
148	    } else {
149	        program
150	            .func(my_ir_generator_info.curr_func.unwrap())
151	            .dfg()
152	            .value(value)
153	            .clone()
154	    }
155	}
156	
157	/// Helper function to build a new value.
158	fn create_new_local_value<'a>(
159	    program: &'a mut Program,
160	    my_ir_generator_info: &'a mut MyIRGeneratorInfo,
161	) -> koopa::ir::builder::LocalBuilder<'a> {
162	    program
163	        .func_mut(
164	            my_ir_generator_info
165	                .curr_func
166	                .expect("You should use create_new_global_value when curr_func is None! "),
167	        )
168	        .dfg_mut()
169	        .new_value()
170	}
171	
172	/// Helper function to build a new basic block.
173	fn create_new_block<'a>(
174	    program: &'a mut Program,
175	    my_ir_generator_info: &'a mut MyIRGeneratorInfo,
176	    name: &str,
177	) -> BasicBlock {
178	    let block = program
179	        .func_mut(my_ir_generator_info.curr_func.unwrap())
180	        .dfg_mut()
181	        .new_bb()
182	        .basic_block(Some(format!("%bb{}_{}", my_ir_generator_info.bb_cnt, name)));
183	    my_ir_generator_info.bb_cnt += 1;
184	    block
185	}
