218	fn build_shape(
219	    shape_exps: &Vec<Exp>,
220	    program: &mut Program,
221	    my_ir_generator_info: &mut MyIRGeneratorInfo,
222	) -> Result<Vec<usize>, String> {
223	    let mut result = vec![];
224	    for exp in shape_exps {
225	        match exp.build(program, my_ir_generator_info)? {
226	            IRExpBuildResult::Const(int) => result.push(int as usize),
227	            IRExpBuildResult::Value(_) => {
228	                return Err(format!("The shape of array must be constant! "))
229	            }
230	        }
231	    }
232	    Ok(result.clone())
233	}
