        let lib_funcs: Vec<(&str, Vec<Type>, Type)> = vec![
            ("getint", vec![], i32_ty.clone()),
            ("getch", vec![], i32_ty.clone()),
            ("getarray", vec![ptr_i32_ty.clone()], i32_ty.clone()),
            ("putint", vec![i32_ty.clone()], unit_ty.clone()),
            ("putch", vec![i32_ty.clone()], unit_ty.clone()),
            ("putarray", vec![i32_ty.clone(), ptr_i32_ty.clone()], unit_ty.clone()),
            ("starttime", vec![], unit_ty.clone()),
            ("stoptime", vec![], unit_ty.clone()),
        ];
        for (name, params, ret) in lib_funcs {
            let func_data = koopa::ir::FunctionData::new_decl(format!("@{}", name), params, ret);
            let func = program.new_func(func_data);
            my_ir_generator_info.function_table.insert(name.to_string(), func);
        }
        match self {
            CompUnit::Default(units) => {
                for unit in units {
                    unit.build(program, my_ir_generator_info)?;
                }
            }
        }
        Ok(IRBuildResult::OK)
    }
}

