impl IRBuildable for BasicStmt {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        match self {
            BasicStmt::AssignStmt(lval, exp) => {
                let exp_value = match exp.build(program, my_ir_generator_info)? {
                    IRExpBuildResult::Const(int) => {
                        create_new_local_value(program, my_ir_generator_info).integer(int)
                    }
                    IRExpBuildResult::Value(value) => value,
                };
                let target = match lval.build(program, my_ir_generator_info)? {
                    IRLValBuildResult::Const(_) => {
                        return Err(format!("Cannot assign to a constant! "))
                    }
                    IRLValBuildResult::TempVal(value) => value,
                    IRLValBuildResult::Addr(ptr) => ptr,
                };
                let store =
                    create_new_local_value(program, my_ir_generator_info).store(exp_value, target);
                insert_local_instructions(program, my_ir_generator_info, [store]);
                Ok(IRBuildResult::OK)
            }
            BasicStmt::Exp(exp) => {
                if let Some(exp) = exp {
                    exp.build(program, my_ir_generator_info)?;
                }
                Ok(IRBuildResult::OK)
            }
            BasicStmt::Block(block) => {
                my_ir_generator_info.symbol_tables.add_new_table();
                // Block::build pops the new symbol table itself.
                block.build(program, my_ir_generator_info)
            }
            BasicStmt::IfStmt(cond, then_stmt, else_stmt) => {
                let cond_value = match cond.build(program, my_ir_generator_info)? {
                    IRExpBuildResult::Const(int) => {
                        create_new_local_value(program, my_ir_generator_info).integer(int)
                    }
                    IRExpBuildResult::Value(value) => value,
                };
                let then_bb = create_new_block(program, my_ir_generator_info, "if_then");
                let else_bb = if else_stmt.is_some() {
                    Some(create_new_block(program, my_ir_generator_info, "if_else"))
                } else {
                    None
                };
                let end_bb = create_new_block(program, my_ir_generator_info, "if_end");
                let branch = create_new_local_value(program, my_ir_generator_info).branch(
                    cond_value,
                    then_bb,
                    else_bb.unwrap_or(end_bb),
                );
                insert_local_instructions(program, my_ir_generator_info, [branch]);
                insert_basic_blocks(program, my_ir_generator_info, [then_bb]);
                my_ir_generator_info.curr_block = Some(then_bb);
                let then_result = then_stmt.build(program, my_ir_generator_info)?;
                if let IRBuildResult::OK = then_result {
                    let jump = create_new_local_value(program, my_ir_generator_info).jump(end_bb);
                    insert_local_instructions(program, my_ir_generator_info, [jump]);
                }
                let mut else_result = IRBuildResult::OK;
                if let (Some(else_bb), Some(else_stmt)) = (else_bb, else_stmt.as_ref()) {
                    insert_basic_blocks(program, my_ir_generator_info, [else_bb]);
                    my_ir_generator_info.curr_block = Some(else_bb);
                    else_result = else_stmt.build(program, my_ir_generator_info)?;
                    if let IRBuildResult::OK = else_result {
                        let jump =
                            create_new_local_value(program, my_ir_generator_info).jump(end_bb);
                        insert_local_instructions(program, my_ir_generator_info, [jump]);
                    }
                }
                insert_basic_blocks(program, my_ir_generator_info, [end_bb]);
                my_ir_generator_info.curr_block = Some(end_bb);
                if else_bb.is_some()
                    && matches!(then_result, IRBuildResult::EARLYSTOPPING)
                    && matches!(else_result, IRBuildResult::EARLYSTOPPING)
                {
                    // Both branches are terminated; end_bb is unreachable.
                    Ok(IRBuildResult::EARLYSTOPPING)
                } else {
                    Ok(IRBuildResult::OK)
                }
            }
            BasicStmt::WhileStmt(cond, body) => {
                let cond_bb = create_new_block(program, my_ir_generator_info, "while_entry");
                let body_bb = create_new_block(program, my_ir_generator_info, "while_body");
                let end_bb = create_new_block(program, my_ir_generator_info, "while_end");
                let jump = create_new_local_value(program, my_ir_generator_info).jump(cond_bb);
                insert_local_instructions(program, my_ir_generator_info, [jump]);
                insert_basic_blocks(program, my_ir_generator_info, [cond_bb]);
                my_ir_generator_info.curr_block = Some(cond_bb);
                let cond_value = match cond.build(program, my_ir_generator_info)? {
                    IRExpBuildResult::Const(int) => {
                        create_new_local_value(program, my_ir_generator_info).integer(int)
                    }
                    IRExpBuildResult::Value(value) => value,
                };
                let branch = create_new_local_value(program, my_ir_generator_info).branch(
                    cond_value,
                    body_bb,
                    end_bb,
                );
                insert_local_instructions(program, my_ir_generator_info, [branch]);
                my_ir_generator_info.break_tgt_blocks.push(end_bb);
                my_ir_generator_info.continue_tgt_blocks.push(cond_bb);
                insert_basic_blocks(program, my_ir_generator_info, [body_bb]);
                my_ir_generator_info.curr_block = Some(body_bb);
                let body_result = body.build(program, my_ir_generator_info)?;
                if let IRBuildResult::OK = body_result {
                    let jump = create_new_local_value(program, my_ir_generator_info).jump(cond_bb);
                    insert_local_instructions(program, my_ir_generator_info, [jump]);
                }
                my_ir_generator_info.break_tgt_blocks.pop();
                my_ir_generator_info.continue_tgt_blocks.pop();
                insert_basic_blocks(program, my_ir_generator_info, [end_bb]);
                my_ir_generator_info.curr_block = Some(end_bb);
                Ok(IRBuildResult::OK)
            }
            BasicStmt::BreakStmt => {
                let target = match my_ir_generator_info.break_tgt_blocks.last() {
                    Some(target) => *target,
                    None => return Err(format!("Break statement outside of a loop! ")),
                };
                let jump = create_new_local_value(program, my_ir_generator_info).jump(target);
                insert_local_instructions(program, my_ir_generator_info, [jump]);
                Ok(IRBuildResult::EARLYSTOPPING)
            }
            BasicStmt::ContinueStmt => {
                let target = match my_ir_generator_info.continue_tgt_blocks.last() {
                    Some(target) => *target,
                    None => return Err(format!("Continue statement outside of a loop! ")),
                };
                let jump = create_new_local_value(program, my_ir_generator_info).jump(target);
                insert_local_instructions(program, my_ir_generator_info, [jump]);
                Ok(IRBuildResult::EARLYSTOPPING)
            }
            BasicStmt::ReturnStmt(exp) => {
                let ret_value = match exp {
                    Some(exp) => Some(match exp.build(program, my_ir_generator_info)? {
                        IRExpBuildResult::Const(int) => {
                            create_new_local_value(program, my_ir_generator_info).integer(int)
                        }
                        IRExpBuildResult::Value(value) => value,
                    }),
                    None => None,
                };
                let ret = create_new_local_value(program, my_ir_generator_info).ret(ret_value);
                insert_local_instructions(program, my_ir_generator_info, [ret]);
                Ok(IRBuildResult::EARLYSTOPPING)
            }
        }
    }
}

