    binary_op: koopa::ir::BinaryOp,
) -> Result<IRExpBuildResult, String> {
    use koopa::ir::BinaryOp;
    // Constant folding.
    if let (IRExpBuildResult::Const(int1), IRExpBuildResult::Const(int2)) = (&result1, &result2)
    {
        let folded = match binary_op {
            BinaryOp::Add => Some(int1.wrapping_add(*int2)),
            BinaryOp::Sub => Some(int1.wrapping_sub(*int2)),
            BinaryOp::Mul => Some(int1.wrapping_mul(*int2)),
            // Do not fold division/modulo by zero: emit the instruction instead.
            BinaryOp::Div => {
                if *int2 != 0 {
                    Some(int1.wrapping_div(*int2))
                } else {
                    None
                }
            }
            BinaryOp::Mod => {
                if *int2 != 0 {
                    Some(int1.wrapping_rem(*int2))
                } else {
                    None
                }
            }
            BinaryOp::Lt => Some((*int1 < *int2) as i32),
            BinaryOp::Gt => Some((*int1 > *int2) as i32),
            BinaryOp::Le => Some((*int1 <= *int2) as i32),
            BinaryOp::Ge => Some((*int1 >= *int2) as i32),
            BinaryOp::Eq => Some((*int1 == *int2) as i32),
            BinaryOp::NotEq => Some((*int1 != *int2) as i32),
            _ => None,
        };
        if let Some(int) = folded {
            return Ok(IRExpBuildResult::Const(int));
        }
    }
    let lhs = match result1 {
        IRExpBuildResult::Const(int) => {
            create_new_local_value(program, my_ir_generator_info).integer(int)
        }
        IRExpBuildResult::Value(value) => value,
    };
    let rhs = match result2 {
        IRExpBuildResult::Const(int) => {
            create_new_local_value(program, my_ir_generator_info).integer(int)
        }
        IRExpBuildResult::Value(value) => value,
    };
    let inst = create_new_local_value(program, my_ir_generator_info).binary(binary_op, lhs, rhs);
    insert_local_instructions(program, my_ir_generator_info, [inst]);
    Ok(IRExpBuildResult::Value(inst))
}

/// Converts a build result into a 0/1 value: folds constants, otherwise
/// emits a `ne value, 0` instruction.
fn build_not_eq_zero(
    result: IRExpBuildResult,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<IRExpBuildResult, String> {
    match result {
        IRExpBuildResult::Const(int) => Ok(IRExpBuildResult::Const((int != 0) as i32)),
        IRExpBuildResult::Value(value) => {
            let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
            let inst = create_new_local_value(program, my_ir_generator_info).binary(
                koopa::ir::BinaryOp::NotEq,
                value,
                zero,
            );
            insert_local_instructions(program, my_ir_generator_info, [inst]);
            Ok(IRExpBuildResult::Value(inst))
        }
    }
}

/// Builds a short-circuiting logical expression (`is_or` selects `||` vs `&&`)
/// using basic blocks. `lhs_result` must be a non-constant build result.
fn build_short_circuit_logic(
    lhs_result: IRExpBuildResult,
    rhs: &impl IRExpBuildable,
    is_or: bool,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<IRExpBuildResult, String> {
    let lhs_value = match lhs_result {
        IRExpBuildResult::Value(value) => value,
        IRExpBuildResult::Const(_) => unreachable!("constant lhs is handled by the caller"),
    };
    // %result = alloc i32 (koopa allows allocs outside the entry block).
    let result =
        create_new_local_value(program, my_ir_generator_info).alloc(Type::get_i32());
    // %c1 = ne lhs, 0; store %c1, %result
    let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
    let c1 = create_new_local_value(program, my_ir_generator_info).binary(
        koopa::ir::BinaryOp::NotEq,
        lhs_value,
        zero,
    );
    let store_c1 = create_new_local_value(program, my_ir_generator_info).store(c1, result);
    insert_local_instructions(program, my_ir_generator_info, [result, c1, store_c1]);
    // br %c1
    let shortcut_bb = create_new_block(
        program,
        my_ir_generator_info,
        if is_or { "lor_true" } else { "land_false" },
    );
    let rhs_bb = create_new_block(program, my_ir_generator_info, "logic_rhs");
    let end_bb = create_new_block(program, my_ir_generator_info, "logic_end");
    let (true_bb, false_bb) = if is_or {
        (shortcut_bb, rhs_bb)
    } else {
        (rhs_bb, shortcut_bb)
    };
    let branch =
        create_new_local_value(program, my_ir_generator_info).branch(c1, true_bb, false_bb);
    insert_local_instructions(program, my_ir_generator_info, [branch]);
    insert_basic_blocks(program, my_ir_generator_info, [shortcut_bb, rhs_bb, end_bb]);
    // Evaluate rhs in its own block.
    my_ir_generator_info.curr_block = Some(rhs_bb);
    let rhs_result = rhs.build(program, my_ir_generator_info)?;
    let rhs_value = match rhs_result {
        IRExpBuildResult::Const(int) => {
            create_new_local_value(program, my_ir_generator_info).integer(int)
        }
        IRExpBuildResult::Value(value) => value,
    };
    let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
    let c2 = create_new_local_value(program, my_ir_generator_info).binary(
        koopa::ir::BinaryOp::NotEq,
        rhs_value,
        zero,
    );
    let store_c2 = create_new_local_value(program, my_ir_generator_info).store(c2, result);
    let jump_end = create_new_local_value(program, my_ir_generator_info).jump(end_bb);
    insert_local_instructions(program, my_ir_generator_info, [c2, store_c2, jump_end]);
    // The shortcut block stores the short-circuited constant.
    my_ir_generator_info.curr_block = Some(shortcut_bb);
    let shortcut_const =
        create_new_local_value(program, my_ir_generator_info).integer(if is_or { 1 } else { 0 });
    let store_shortcut =
        create_new_local_value(program, my_ir_generator_info).store(shortcut_const, result);
    let jump_end = create_new_local_value(program, my_ir_generator_info).jump(end_bb);
    insert_local_instructions(program, my_ir_generator_info, [store_shortcut, jump_end]);
    // The end block loads the result.
    my_ir_generator_info.curr_block = Some(end_bb);
    let value = create_new_local_value(program, my_ir_generator_info).load(result);
    insert_local_instructions(program, my_ir_generator_info, [value]);
    Ok(IRExpBuildResult::Value(value))
}

