/// Drills into an `Exp` to check whether it is syntactically a plain `LVal`
/// (Exp -> LOrExp -> LAndExp -> EqExp -> RelExp -> AddExp -> MulExp ->
/// UnaryExp::PrimaryExp -> PrimaryExp::LVal). Used to fetch the address of an
/// array argument passed to a pointer parameter.
fn exp_as_lval(exp: &Exp) -> Option<&LVal> {
    let Exp::LOrExp(LOrExp::LAndExp(LAndExp::EqExp(EqExp::RelExp(RelExp::AddExp(
        AddExp::MulExp(MulExp::UnaryExp(UnaryExp::PrimaryExp(PrimaryExp::LVal(lval)))),
    ))))) = exp
    else {
        return None;
    };
    Some(lval)
}

impl IRExpBuildable for UnaryExp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            UnaryExp::PrimaryExp(exp) => exp.build(program, my_ir_generator_info),
            UnaryExp::PlusUnaryExp(exp) => exp.build(program, my_ir_generator_info),
            UnaryExp::MinusUnaryExp(exp) => {
                match exp.build(program, my_ir_generator_info)? {
                    IRExpBuildResult::Const(int) => Ok(IRExpBuildResult::Const(int.wrapping_neg())),
                    IRExpBuildResult::Value(value) => {
                        // sub 0, value
                        let zero =
                            create_new_local_value(program, my_ir_generator_info).integer(0);
                        let inst = create_new_local_value(program, my_ir_generator_info).binary(
                            koopa::ir::BinaryOp::Sub,
                            zero,
                            value,
                        );
                        insert_local_instructions(program, my_ir_generator_info, [inst]);
                        Ok(IRExpBuildResult::Value(inst))
                    }
                }
            }
            UnaryExp::NotUnaryExp(exp) => match exp.build(program, my_ir_generator_info)? {
                IRExpBuildResult::Const(int) => {
                    Ok(IRExpBuildResult::Const((int == 0) as i32))
                }
                IRExpBuildResult::Value(value) => {
                    // eq value, 0
                    let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
                    let inst = create_new_local_value(program, my_ir_generator_info).binary(
                        koopa::ir::BinaryOp::Eq,
                        value,
                        zero,
                    );
                    insert_local_instructions(program, my_ir_generator_info, [inst]);
                    Ok(IRExpBuildResult::Value(inst))
                }
            },
            UnaryExp::FuncCall(ident, args) => {
                let func = match my_ir_generator_info.function_table.get(&ident.content) {
                    Some(func) => *func,
                    None => {
                        return Err(format!("Undeclared function: {}", ident.content));
                    }
                };
                let func_type = program.func(func).ty().clone();
                let param_types = match func_type.kind() {
                    TypeKind::Function(params, _) => params.clone(),
                    _ => return Err(format!("{} is not a function", ident.content)),
                };
                if param_types.len() != args.len() {
                    return Err(format!(
                        "Function {} expects {} arguments, but {} were given",
                        ident.content,
                        param_types.len(),
                        args.len()
                    ));
                }
                let mut arg_values = vec![];
                for (arg, param_type) in args.iter().zip(param_types.iter()) {
                    match param_type.kind() {
                        TypeKind::Pointer(_) => {
                            // Pointer parameter: the argument must be an LVal
                            // whose address (after array decay) is passed.
                            let lval = exp_as_lval(arg).ok_or_else(|| {
                                format!(
                                    "Function {} expects an array argument, but a non-array expression was given",
                                    ident.content
                                )
                            })?;
                            match lval.build(program, my_ir_generator_info)? {
                                IRLValBuildResult::Addr(ptr) => arg_values.push(ptr),
                                IRLValBuildResult::TempVal(value) => arg_values.push(value),
                                IRLValBuildResult::Const(_) => {
                                    return Err(format!(
                                        "Function {} expects an array argument, but a constant was given",
                                        ident.content
                                    ));
                                }
                            }
                        }
                        _ => match arg.build(program, my_ir_generator_info)? {
                            IRExpBuildResult::Const(int) => arg_values.push(
                                create_new_local_value(program, my_ir_generator_info)
                                    .integer(int),
                            ),
                            IRExpBuildResult::Value(value) => arg_values.push(value),
                        },
                    }
                }
                let call =
                    create_new_local_value(program, my_ir_generator_info).call(func, arg_values);
                insert_local_instructions(program, my_ir_generator_info, [call]);
                Ok(IRExpBuildResult::Value(call))
            }
        }
    }
}

impl IRExpBuildable for PrimaryExp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            PrimaryExp::BracedExp(exp) => exp.build(program, my_ir_generator_info),
            PrimaryExp::LVal(lval) => match lval.build(program, my_ir_generator_info)? {
                IRLValBuildResult::Const(int) => Ok(IRExpBuildResult::Const(int)),
                IRLValBuildResult::TempVal(value) => Ok(IRExpBuildResult::Value(value)),
                IRLValBuildResult::Addr(ptr) => {
                    let load = create_new_local_value(program, my_ir_generator_info).load(ptr);
                    insert_local_instructions(program, my_ir_generator_info, [load]);
                    Ok(IRExpBuildResult::Value(load))
                }
            },
            PrimaryExp::Number(number) => number.build(program, my_ir_generator_info),
        }
    }
}

