fn get_element_in_ndarray(
    array_or_pointer: Value,
    indexes: &[Value],
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> IRLValBuildResult {
    // The pointee type of the symbol-table value (an alloc slot or a global).
    let value_type = get_valuedata(array_or_pointer, program, my_ir_generator_info)
        .ty()
        .clone();
    let mut pointee = match value_type.kind() {
        TypeKind::Pointer(inner) => inner.clone(),
        _ => unreachable!("array_or_pointer must be a pointer"),
    };

    if indexes.is_empty() {
        return match pointee.kind() {
            // Scalar variable: callers load from the address themselves.
            TypeKind::Int32 => IRLValBuildResult::Addr(array_or_pointer),
            // Real array: decay to a pointer to its first element.
            TypeKind::Array(..) => {
                let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
                let gep = create_new_local_value(program, my_ir_generator_info)
                    .get_elem_ptr(array_or_pointer, zero);
                insert_local_instructions(program, my_ir_generator_info, [gep]);
                IRLValBuildResult::Addr(gep)
            }
            // Array parameter: the slot holds a pointer; loading it yields the
            // element pointer directly.
            TypeKind::Pointer(..) => {
                let loaded =
                    create_new_local_value(program, my_ir_generator_info).load(array_or_pointer);
                insert_local_instructions(program, my_ir_generator_info, [loaded]);
                IRLValBuildResult::Addr(loaded)
            }
            _ => unreachable!("unsupported pointee type of array_or_pointer"),
        };
    }

    let mut cur = array_or_pointer;
    let mut start = 0;
    if matches!(pointee.kind(), TypeKind::Pointer(_)) {
        // Array parameter: load the actual pointer first. The first index
        // steps through the pointer itself (getptr), subsequent indexes
        // dereference array layers (getelemptr).
        let loaded = create_new_local_value(program, my_ir_generator_info).load(cur);
        insert_local_instructions(program, my_ir_generator_info, [loaded]);
        pointee = match pointee.kind() {
            TypeKind::Pointer(inner) => inner.clone(),
            _ => unreachable!(),
        };
        let gep =
            create_new_local_value(program, my_ir_generator_info).get_ptr(loaded, indexes[0]);
        insert_local_instructions(program, my_ir_generator_info, [gep]);
        cur = gep;
        start = 1;
    }
    for index in &indexes[start..] {
        let gep = create_new_local_value(program, my_ir_generator_info).get_elem_ptr(cur, *index);
        insert_local_instructions(program, my_ir_generator_info, [gep]);
        pointee = match pointee.kind() {
            TypeKind::Array(element, _) => element.clone(),
            _ => unreachable!("too many indexes for the array type"),
        };
        cur = gep;
    }
    // Partial indexing (e.g. `a[i]` of a 2-D array used as a pointer
    // argument): decay the remaining array to a pointer to its first element.
    if matches!(pointee.kind(), TypeKind::Array(..)) {
        let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
        let gep = create_new_local_value(program, my_ir_generator_info).get_elem_ptr(cur, zero);
        insert_local_instructions(program, my_ir_generator_info, [gep]);
        cur = gep;
    }
    IRLValBuildResult::Addr(cur)
}

