//! Convert a single Koopa IR component into assembly code.

use super::{
    MyBBValueTable, ARG_SIZE, REGISTER_FOR_ARGS, REGISTER_NAMES, REG_A0, REG_RA, REG_SP, REG_X31,
};
use koopa::ir::{
    entities::ValueData, values::Aggregate, BinaryOp, FunctionData, Program, TypeKind, ValueKind,
};

pub trait AssemblyBuildable {
    fn build(&self, program: &Program) -> Result<Vec<String>, String>;
}

impl AssemblyBuildable for Program {
    fn build(&self, _: &Program) -> Result<Vec<String>, String> {
        let mut codes = Vec::new();
        // Global variables (each one emits its own `.data` directive).
        for value_data in self.borrow_values().values() {
            codes.extend(value_data.build(self)?);
        }
        // Function definitions; skip declarations (e.g. SysY library functions).
        for &func in self.func_layout() {
            let func_data = self.func(func);
            if func_data.layout().entry_bb().is_none() {
                continue;
            }
            codes.extend(func_data.build(self)?);
        }
        Ok(codes)
    }
}

fn binary_op_to_assembly(
    binary: &koopa::ir::values::Binary,
    reg_ans: usize,
    reg1: usize,
    reg2: usize,
) -> String {
    let ans = REGISTER_NAMES[reg_ans];
    let r1 = REGISTER_NAMES[reg1];
    let r2 = REGISTER_NAMES[reg2];
    match binary.op() {
        BinaryOp::Add => format!("  add\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Sub => format!("  sub\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Mul => format!("  mul\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Div => format!("  div\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Mod => format!("  rem\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Eq => format!("  xor\t{}, {}, {}\n  seqz\t{}, {}", ans, r1, r2, ans, ans),
        BinaryOp::NotEq => format!("  xor\t{}, {}, {}\n  snez\t{}, {}", ans, r1, r2, ans, ans),
        BinaryOp::Lt => format!("  slt\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Gt => format!("  sgt\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Le => format!("  sgt\t{}, {}, {}\n  seqz\t{}, {}", ans, r1, r2, ans, ans),
        BinaryOp::Ge => format!("  slt\t{}, {}, {}\n  seqz\t{}, {}", ans, r1, r2, ans, ans),
        BinaryOp::And => format!("  and\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Or => format!("  or\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Xor => format!("  xor\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Shl => format!("  sll\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Shr => format!("  srl\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Sar => format!("  sra\t{}, {}, {}", ans, r1, r2),
    }
}

/// Recursively flattens a global aggregate initializer into `.word` lines.
fn init_global_aggregate(aggr: &Aggregate, program: &Program) -> Vec<String> {
    let mut codes = Vec::new();
    for &elem in aggr.elems() {
        let elem_data = program.borrow_value(elem);
        match elem_data.kind() {
            ValueKind::Integer(integer) => codes.push(format!("  .word\t{}", integer.value())),
            ValueKind::ZeroInit(_) => codes.push(format!("  .zero\t{}", elem_data.ty().size())),
            ValueKind::Aggregate(inner) => codes.extend(init_global_aggregate(inner, program)),
            _ => unreachable!("Unsupported aggregate element in global initializer! "),
        }
    }
    codes
}

impl AssemblyBuildable for ValueData {
    /// Used to handle global variable declarations.
    /// The ValueData's kind should be GlobalAlloc. Or it will panic.
    fn build(&self, program: &Program) -> Result<Vec<String>, String> {
        let mut codes = Vec::new();
        let name = match self.name() {
            Some(name) => name[1..].to_string(), // strip '@'
            None => return Err("Global value must have a name! ".to_string()),
        };
        match self.kind() {
            ValueKind::GlobalAlloc(global_alloc) => {
                codes.push("  .data".to_string());
                codes.push(format!("  .globl {}", name));
                codes.push(format!("{}:", name));
                let init = program.borrow_value(global_alloc.init());
                match init.kind() {
                    ValueKind::Integer(integer) => {
                        codes.push(format!("  .word\t{}", integer.value()))
                    }
                    ValueKind::ZeroInit(_) => {
                        // self.ty() is *T; the allocation occupies sizeof(T) bytes.
                        let size = match self.ty().kind() {
                            TypeKind::Pointer(base_ty) => base_ty.size(),
                            _ => ARG_SIZE,
                        };
                        codes.push(format!("  .zero\t{}", size));
                    }
                    ValueKind::Aggregate(aggr) => {
                        codes.extend(init_global_aggregate(aggr, program));
                    }
                    _ => return Err("Unsupported global initializer! ".to_string()),
                }
                Ok(codes)
            }
            _ => Err("ValueData::build only supports global allocations! ".to_string()),
        }
    }
}

impl AssemblyBuildable for FunctionData {
    fn build(&self, program: &Program) -> Result<Vec<String>, String> {
        let mut codes = Vec::new();
        let func_name = self.name()[1..].to_string(); // strip '@'
        let dfg = self.dfg();

        // ---- Compute the stack frame before emitting any instruction ----
        let mut has_call = false;
        let mut max_call_args = 0usize;
        for value_data in dfg.values().values() {
            if let ValueKind::Call(call) = value_data.kind() {
                has_call = true;
                max_call_args = max_call_args.max(call.args().len());
            }
        }
        let mut table = MyBBValueTable::new(program, self);
        // Outgoing arguments (beyond a0-a7) live at the bottom of the frame.
        let mut offset = max_call_args.saturating_sub(REGISTER_FOR_ARGS.len()) * ARG_SIZE;
        // One slot per non-unit, non-constant value (allocs of arrays get the
        // whole array's size).
        for (&value, value_data) in dfg.values() {
            if value_data.ty().is_unit() || value_data.kind().is_const() {
                continue;
            }
            if let ValueKind::FuncArgRef(arg) = value_data.kind() {
                if arg.index() >= REGISTER_FOR_ARGS.len() {
                    continue; // lives in the caller's frame; handled below
                }
            }
            let size = match value_data.kind() {
                ValueKind::Alloc(_) => match value_data.ty().kind() {
                    TypeKind::Pointer(base_ty) => base_ty.size(),
                    _ => ARG_SIZE,
                },
                _ => ARG_SIZE,
            };
            table.local_value_location.insert(value, offset);
            offset += size;
        }
        if has_call {
            offset += ARG_SIZE; // slot for ra
        }
        let frame_size = (offset + 15) / 16 * 16;
        let ra_offset = frame_size - ARG_SIZE;
        // Stack parameters (index >= 8) stay where the caller put them.
        for (i, &param) in self.params().iter().enumerate() {
            if i >= REGISTER_FOR_ARGS.len() {
                table.local_value_location.insert(
                    param,
                    frame_size + (i - REGISTER_FOR_ARGS.len()) * ARG_SIZE,
                );
            }
        }

        // ---- Prologue ----
        codes.push("  .text".to_string());
        codes.push(format!("  .globl {}", func_name));
        codes.push(format!("{}:", func_name));
        if frame_size > 0 {
            if frame_size <= 2048 {
                codes.push(format!(
                    "  addi\t{}, {}, -{}",
                    REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_SP], frame_size
                ));
            } else {
                codes.push(format!("  li\t{}, -{}", REGISTER_NAMES[REG_X31], frame_size));
                codes.push(format!(
                    "  add\t{}, {}, {}",
                    REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_X31]
                ));
            }
        }
        if has_call {
            codes.extend(table.store_with_offset(REG_RA, ra_offset as isize));
        }
        // Save incoming register arguments to their slots.
        for (i, &param) in self.params().iter().enumerate() {
            if i < REGISTER_FOR_ARGS.len() {
                let slot = *table
                    .local_value_location
                    .get(&param)
                    .expect("Parameter must own a stack slot! ");
                codes.extend(table.store_with_offset(REGISTER_FOR_ARGS[i], slot as isize));
            }
        }

        // ---- Basic blocks ----
        let block_label = |bb: koopa::ir::BasicBlock| -> String {
            let name = dfg
                .bb(bb)
                .name()
                .as_ref()
                .expect("Basic block must have a name! ");
            format!("{}_{}", func_name, &name[1..]) // strip '%'
        };
        for (&bb, node) in self.layout().bbs().iter() {
            codes.push(format!("{}:", block_label(bb)));
            // Flush the register cache at every block boundary. Memory is
            // always up to date (write-through + spill-at-definition).
            codes.extend(table.store_local_variables());
            codes.extend(table.store_global_variables());
            for &inst in node.insts().keys() {
                let inst_data = dfg.value(inst).clone();
                match inst_data.kind() {
                    ValueKind::Alloc(_) => {
                        // Slot preassigned; nothing to do at runtime.
                    }
                    ValueKind::Store(store) => {
                        let (reg, value_codes) =
                            table.want_to_visit_value(store.value(), true, None);
                        codes.extend(value_codes);
                        let dest = store.dest();
                        let dest_data = match dest.is_global() {
                            true => program.borrow_value(dest).clone(),
                            false => dfg.value(dest).clone(),
                        };
                        match dest_data.kind() {
                            ValueKind::Alloc(_) => {
                                let slot = *table
                                    .local_value_location
                                    .get(&dest)
                                    .expect("Local alloc must own a stack slot! ");
                                codes.extend(table.store_with_offset(reg, slot as isize));
                            }
                            ValueKind::GlobalAlloc(_) => {
                                let name = dest_data.name().as_ref().unwrap()[1..].to_string();
                                codes.extend(table.store_global(reg, name));
                            }
                            ValueKind::GetElemPtr(_) | ValueKind::GetPtr(_) => {
                                let (addr_reg, addr_codes) = table.get_absolute_location(dest);
                                codes.extend(addr_codes);
                                codes.push(format!(
                                    "  sw\t{}, 0({})",
                                    REGISTER_NAMES[reg], REGISTER_NAMES[addr_reg]
                                ));
                            }
                            _ => {
                                // The destination is a pointer value produced by
                                // another instruction (load / argument / ...).
                                let (addr_reg, addr_codes) =
                                    table.want_to_visit_value(dest, true, None);
                                codes.extend(addr_codes);
                                codes.push(format!(
                                    "  sw\t{}, 0({})",
                                    REGISTER_NAMES[reg], REGISTER_NAMES[addr_reg]
                                ));
                            }
                        }
                    }
                    ValueKind::Load(load) => {
                        let (reg, reg_codes) = table.want_to_visit_value(inst, false, None);
                        codes.extend(reg_codes);
                        let src = load.src();
                        let src_data = match src.is_global() {
                            true => program.borrow_value(src).clone(),
                            false => dfg.value(src).clone(),
                        };
                        match src_data.kind() {
                            ValueKind::Alloc(_) => {
                                let slot = *table
                                    .local_value_location
                                    .get(&src)
                                    .expect("Local alloc must own a stack slot! ");
                                codes.extend(table.load_with_offset(reg, slot as isize));
                            }
                            ValueKind::GlobalAlloc(_) => {
                                let name = src_data.name().as_ref().unwrap()[1..].to_string();
                                codes.extend(table.load_global(reg, name));
                            }
                            ValueKind::GetElemPtr(_) | ValueKind::GetPtr(_) => {
                                let (addr_reg, addr_codes) = table.get_absolute_location(src);
                                codes.extend(addr_codes);
                                codes.push(format!(
                                    "  lw\t{}, 0({})",
                                    REGISTER_NAMES[reg], REGISTER_NAMES[addr_reg]
                                ));
                            }
                            _ => {
                                let (addr_reg, addr_codes) =
                                    table.want_to_visit_value(src, true, None);
                                codes.extend(addr_codes);
                                codes.push(format!(
                                    "  lw\t{}, 0({})",
                                    REGISTER_NAMES[reg], REGISTER_NAMES[addr_reg]
                                ));
                            }
                        }
                        // Spill the result to its slot at definition time.
                        let slot = *table
                            .local_value_location
                            .get(&inst)
                            .expect("Instruction result must own a stack slot! ");
                        codes.extend(table.store_with_offset(reg, slot as isize));
                    }
                    ValueKind::Binary(binary) => {
                        let (reg1, lhs_codes) =
                            table.want_to_visit_value(binary.lhs(), true, None);
                        codes.extend(lhs_codes);
                        let (reg2, rhs_codes) =
                            table.want_to_visit_value(binary.rhs(), true, None);
                        codes.extend(rhs_codes);
                        let (reg_ans, ans_codes) = table.want_to_visit_value(inst, false, None);
                        codes.extend(ans_codes);
                        codes.push(binary_op_to_assembly(binary, reg_ans, reg1, reg2));
                        let slot = *table
                            .local_value_location
                            .get(&inst)
                            .expect("Instruction result must own a stack slot! ");
                        codes.extend(table.store_with_offset(reg_ans, slot as isize));
                    }
                    ValueKind::Jump(jump) => {
                        codes.extend(table.store_local_variables());
                        codes.extend(table.store_global_variables());
                        codes.push(format!("  j\t{}", block_label(jump.target())));
                    }
                    ValueKind::Branch(branch) => {
                        let (reg, cond_codes) =
                            table.want_to_visit_value(branch.cond(), true, None);
                        codes.extend(cond_codes);
                        codes.extend(table.store_local_variables());
                        codes.extend(table.store_global_variables());
                        codes.push(format!(
                            "  bnez\t{}, {}",
                            REGISTER_NAMES[reg],
                            block_label(branch.true_bb())
                        ));
                        codes.push(format!("  j\t{}", block_label(branch.false_bb())));
                    }
                    ValueKind::Call(call) => {
                        let callee_name = program.func(call.callee()).name()[1..].to_string();
                        for (i, &arg) in call.args().iter().enumerate() {
                            if i < REGISTER_FOR_ARGS.len() {
                                let (_, arg_codes) = table.want_to_visit_value(
                                    arg,
                                    true,
                                    Some(REGISTER_FOR_ARGS[i]),
                                );
                                codes.extend(arg_codes);
                            } else {
                                let (reg, arg_codes) =
                                    table.want_to_visit_value(arg, true, None);
                                codes.extend(arg_codes);
                                codes.extend(
                                    table.store_with_offset(
                                        reg,
                                        ((i - REGISTER_FOR_ARGS.len()) * ARG_SIZE) as isize,
                                    ),
                                );
                            }
                        }
                        codes.push(format!("  call\t{}", callee_name));
                        // All caller-saved registers are clobbered; every
                        // value's slot is up to date, so just drop the cache.
                        codes.extend(table.store_local_variables());
                        codes.extend(table.store_global_variables());
                        if !inst_data.ty().is_unit() {
                            let slot = *table
                                .local_value_location
                                .get(&inst)
                                .expect("Call result must own a stack slot! ");
                            codes.extend(table.store_with_offset(REG_A0, slot as isize));
                            table.__update_user(REG_A0, inst);
                        }
                    }
                    ValueKind::Return(ret) => {
                        if let Some(value) = ret.value() {
                            let (_, ret_codes) =
                                table.want_to_visit_value(value, true, Some(REG_A0));
                            codes.extend(ret_codes);
                        }
                        if has_call {
                            codes.extend(table.load_with_offset(REG_RA, ra_offset as isize));
                        }
                        if frame_size > 0 {
                            if frame_size <= 2047 {
                                codes.push(format!(
                                    "  addi\t{}, {}, {}",
                                    REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_SP], frame_size
                                ));
                            } else {
                                codes.push(format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], frame_size));
                                codes.push(format!(
                                    "  add\t{}, {}, {}",
                                    REGISTER_NAMES[REG_SP],
                                    REGISTER_NAMES[REG_SP],
                                    REGISTER_NAMES[REG_X31]
                                ));
                            }
                        }
                        codes.push("  ret".to_string());
                    }
                    ValueKind::GetElemPtr(_) | ValueKind::GetPtr(_) => {
                        let (addr_reg, addr_codes) = table.get_absolute_location(inst);
                        codes.extend(addr_codes);
                        // Spill the computed address to its slot at definition.
                        let slot = *table
                            .local_value_location
                            .get(&inst)
                            .expect("Instruction result must own a stack slot! ");
                        codes.extend(table.store_with_offset(addr_reg, slot as isize));
                        table.__update_user(addr_reg, inst);
                    }
                    _ => {
                        return Err(format!(
                            "Unsupported instruction kind in assembly builder: {:?}",
                            inst_data.kind()
                        ))
                    }
                }
            }
        }
        Ok(codes)
    }
}

